<script>
document.addEventListener('DOMContentLoaded',()=>{
const balances=@json($balanceOptions);
const medicines=@json($medicineOptions);
const initial=@json($initialItems); const priceCandidates=@json($issueSalePrices); let index=0; const rows=document.getElementById('rows');
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));}
function addRow(item={}){const tr=document.createElement('tr');tr.className='border-t align-top';const meds=medicines.map(m=>`<option value="${m.id}" ${String(m.id)===String(item.medicine_id||'')?'selected':''}>${m.text}</option>`).join('');tr.innerHTML=`<td class="p-3"><select name="items[${index}][medicine_id]" class="medicine min-h-11 w-full rounded-xl border px-3"><option value="">Chọn thuốc</option>${meds}</select></td><td class="p-3"><select class="lot min-h-11 w-full rounded-xl border px-3"></select><div class="shortage-ui mt-2 hidden items-center gap-2"><span class="shortage-badge rounded-full bg-amber-100 px-2.5 py-1 text-[11px] font-bold text-amber-800"></span><button type="button" class="supply-note-toggle text-[11px] font-bold text-indigo-700 hover:underline">+ Ghi chú cung ứng</button></div><div class="supply-saved mt-2 hidden items-center gap-2 text-[11px]"><span class="rounded-full bg-emerald-50 px-2.5 py-1 font-bold text-emerald-700">✓ Đã có ghi chú</span><button type="button" class="supply-note-edit font-bold text-indigo-700 hover:underline">Sửa</button></div><input type="hidden" class="expected-supply-date" name="items[${index}][expected_supply_date]" value="${item.expected_supply_date||''}"><input type="hidden" class="supply-note-value" name="items[${index}][supply_note]" value="${escapeHtml(item.supply_note||'')}"></td><td class="stock p-3 text-right font-semibold">—</td><td class="p-3"><input name="items[${index}][quantity]" value="${formatViNumber(item.quantity??0,3)}" type="text" inputmode="decimal" required class="qty min-h-11 w-full rounded-xl border px-3 text-right tabular-nums"><p class="warn mt-1 hidden text-xs font-semibold text-rose-600"></p></td><td class="p-3"><input name="items[${index}][unit_price]" value="${formatViNumber(item.unit_price??0,2)}" type="text" inputmode="decimal" required class="price min-h-11 w-full rounded-xl border px-3 text-right tabular-nums"><div class="mt-1 flex min-h-5 items-center justify-between gap-2"><p class="price-source truncate text-[11px] text-slate-500">Đang tải giá bảng...</p><button type="button" class="reset-price shrink-0 text-[11px] font-semibold text-indigo-700 hover:underline">Đặt lại giá gốc</button></div></td><td class="total p-3 text-right font-bold">0 đ</td><td class="p-3 text-right"><button type="button" class="remove text-sm font-semibold text-rose-600">Xóa</button></td>`;rows.appendChild(tr);index++;fillLots(tr,item);setOriginalPrice(tr);tr.querySelector('.medicine').addEventListener('change',()=>{fillLots(tr,{});setOriginalPrice(tr);});tr.querySelector('.lot').addEventListener('change',()=>update(tr));tr.querySelector('.supply-note-toggle').addEventListener('click',()=>openSupplyModal(tr));tr.querySelector('.supply-note-edit').addEventListener('click',()=>openSupplyModal(tr));const qty=tr.querySelector('.qty'),price=tr.querySelector('.price');qty.addEventListener('input',()=>update(tr));qty.addEventListener('blur',()=>{qty.value=formatViNumber(parseViNumber(qty.value),3);update(tr);});price.addEventListener('input',()=>update(tr));price.addEventListener('blur',()=>{price.value=formatViNumber(parseViNumber(price.value),2);update(tr);});tr.querySelector('.reset-price').addEventListener('click',()=>{price.value=formatViNumber(Number(tr.dataset.originalPrice||0),2);update(tr);price.focus();});tr.querySelector('.remove').addEventListener('click',()=>{tr.remove();refreshSummary();});refreshSummary();}
function fillLots(tr,item){const medicine=tr.querySelector('.medicine').value;const lots=balances.filter(b=>String(b.medicine_id)===String(medicine));const select=tr.querySelector('.lot');select.innerHTML='<option value="">Chọn lô</option>'+lots.map(b=>`<option value="${b.id}" ${b.batch===item.batch_number&&b.expiry===item.expiry_date?'selected':''}>${b.batch} · HSD ${new Date(b.expiry+'T00:00:00').toLocaleDateString('vi-VN')} · Tồn ${new Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(b.quantity)}</option>`).join('');select.name=`items[${[...rows.children].indexOf(tr)}][balance_id]`;update(tr);}
function selectedPriceCandidate(medicineId){const listId=document.getElementById('price-list')?.value;const date=document.getElementById('issue-date')?.value;return priceCandidates.find(c=>String(c.price_list_id)===String(listId)&&String(c.medicine_id)===String(medicineId)&&(!c.item_effective_from||c.item_effective_from<=date)&&(!c.item_effective_to||c.item_effective_to>=date)&&(!c.list_effective_from||c.list_effective_from<=date)&&(!c.list_effective_to||c.list_effective_to>=date))||null;}
function setOriginalPrice(tr){const medicineId=tr.querySelector('.medicine')?.value;const candidate=selectedPriceCandidate(medicineId);const original=Number(candidate?.company_sale_price??0);tr.dataset.originalPrice=String(original);const source=tr.querySelector('.price-source');source.textContent=candidate?`Giá bảng: ${formatViNumber(original,2)} đ · ${candidate.price_list_code||candidate.price_list_name||'Bảng giá'}`:'Chưa có giá bảng · có thể nhập tay';update(tr);}
function parseViNumber(value){const raw=String(value??'').trim().replace(/\s/g,'');if(!raw)return 0;if(raw.includes(','))return Number(raw.replace(/\./g,'').replace(',','.'))||0;const dots=(raw.match(/\./g)||[]).length;if(dots>1||(dots===1&&/\.\d{3}$/.test(raw)))return Number(raw.replace(/\./g,''))||0;return Number(raw)||0;}
function formatViNumber(value,maximumFractionDigits=3){return new Intl.NumberFormat('vi-VN',{maximumFractionDigits}).format(Number(value)||0);}
function refreshPostState(){const button=document.getElementById('save-post-issue');if(!button)return;const active=[...rows.querySelectorAll('tr')];const postable=active.filter(tr=>!(tr.querySelector('.supply-note-value')?.value.trim()));const ready=postable.length>0&&postable.every(tr=>{const b=balances.find(x=>String(x.id)===String(tr.querySelector('.lot')?.value));const q=parseViNumber(tr.querySelector('.qty')?.value);return !!b&&q>0&&q<=Number(b.quantity||0)+0.00005;});button.disabled=!ready;button.title=ready?(postable.length<active.length?'Ghi sổ các mặt hàng đủ hàng; mặt hàng có ghi chú cung ứng sẽ không xuất kho':'Lưu thay đổi và ghi sổ phiếu'):(postable.length===0?'Toàn bộ mặt hàng đang chờ cung ứng':'Chọn đủ lô và bảo đảm số lượng thực xuất không vượt tồn kho');}
function refreshSummary(){const active=[...rows.querySelectorAll('tr')];const quantity=active.reduce((sum,tr)=>sum+parseViNumber(tr.querySelector('.qty')?.value),0);const value=active.reduce((sum,tr)=>sum+(parseViNumber(tr.querySelector('.qty')?.value)*parseViNumber(tr.querySelector('.price')?.value)),0);const postable=active.filter(tr=>!(tr.querySelector('.supply-note-value')?.value.trim()));const postedValue=postable.reduce((sum,tr)=>sum+(parseViNumber(tr.querySelector('.qty')?.value)*parseViNumber(tr.querySelector('.price')?.value)),0);const deferredValue=Math.max(0,value-postedValue);const qText=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(quantity),vText=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(value)+' đ';document.getElementById('summary-lines').textContent=active.length;document.getElementById('summary-quantity').textContent=qText;document.getElementById('summary-value').textContent=vText;document.getElementById('aside-lines').textContent=active.length;document.getElementById('aside-quantity').textContent=qText;document.getElementById('aside-value').textContent=vText;const postValue=document.getElementById('aside-post-value'),deferred=document.getElementById('aside-deferred-value');if(postValue)postValue.textContent=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(postedValue)+' đ';if(deferred)deferred.textContent=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(deferredValue)+' đ';refreshPostState();}
function update(tr){const medicineId=tr.querySelector('.medicine').value;const b=balances.find(x=>String(x.id)===String(tr.querySelector('.lot').value));const q=parseViNumber(tr.querySelector('.qty').value),p=parseViNumber(tr.querySelector('.price').value),stock=Number(b?.quantity||0),neg=b&&q>stock;const totalStock=balances.filter(x=>String(x.medicine_id)===String(medicineId)).reduce((sum,x)=>sum+Number(x.quantity||0),0);const shortage=Math.max(0,q-totalStock);const hasShortage=q>0&&shortage>0.00005;const note=tr.querySelector('.supply-note-value')?.value.trim()||'';const shortageUi=tr.querySelector('.shortage-ui'),saved=tr.querySelector('.supply-saved'),badge=tr.querySelector('.shortage-badge');shortageUi?.classList.toggle('hidden',!hasShortage||!!note);shortageUi?.classList.toggle('flex',hasShortage&&!note);saved?.classList.toggle('hidden',!hasShortage||!note);saved?.classList.toggle('flex',hasShortage&&!!note);if(badge)badge.textContent=totalStock<=0?'Chưa có tồn':`Thiếu ${formatViNumber(shortage,3)}`;tr.querySelector('.stock').textContent=b?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(stock):(totalStock>0?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(totalStock):'—');tr.querySelector('.total').textContent=new Intl.NumberFormat('vi-VN').format(q*p)+' đ';const input=tr.querySelector('.qty'),warn=tr.querySelector('.warn');input.classList.toggle('border-rose-500',!!neg);input.classList.toggle('bg-rose-50',!!neg);warn.classList.toggle('hidden',!neg);warn.textContent=neg?`⚠ Tồn sau xuất: ${new Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(stock-q)}`:'';refreshSummary();}
const supplyModal=document.getElementById('supply-note-modal');let supplyRow=null;
function openSupplyModal(tr){supplyRow=tr;document.getElementById('supply-modal-medicine').textContent=tr.querySelector('.medicine')?.selectedOptions?.[0]?.textContent||'';document.getElementById('supply-modal-date').value=tr.querySelector('.expected-supply-date')?.value||'';document.getElementById('supply-modal-note').value=tr.querySelector('.supply-note-value')?.value||'';supplyModal?.showModal();}
function closeSupplyModal(){supplyModal?.close();supplyRow=null;}
document.getElementById('supply-modal-close')?.addEventListener('click',closeSupplyModal);document.getElementById('supply-modal-cancel')?.addEventListener('click',closeSupplyModal);
document.getElementById('supply-modal-save')?.addEventListener('click',()=>{if(!supplyRow)return;const note=document.getElementById('supply-modal-note').value.trim();if(!note){document.getElementById('supply-modal-note').focus();return;}supplyRow.querySelector('.expected-supply-date').value=document.getElementById('supply-modal-date').value;supplyRow.querySelector('.supply-note-value').value=note;const row=supplyRow;closeSupplyModal();update(row);});
document.getElementById('issue-edit-form')?.addEventListener('submit',()=>{rows.querySelectorAll('tr').forEach((tr)=>{const q=tr.querySelector('.qty'),p=tr.querySelector('.price');if(q)q.value=String(parseViNumber(q.value));if(p)p.value=String(parseViNumber(p.value));});});
initial.forEach(addRow);if(!initial.length)addRow();document.getElementById('add-row').addEventListener('click',()=>addRow());
document.getElementById('issue-date')?.addEventListener('change',()=>rows.querySelectorAll('tr').forEach(setOriginalPrice));
});
</script>
@endsection
